#include <algorithm>
#include <iostream>
#include <string>
using namespace std;

int main() {
    string w;
    cin >> w;
    int n = w.size();
    string best;
    bool have = false;
    for (int k = 1; k <= n; k++) {
        string p = w.substr(0, k);
        reverse(p.begin(), p.end());
        p += w.substr(k);  // reverse the prefix of length k
        string s = w.substr(n - k);
        reverse(s.begin(), s.end());
        s = w.substr(0, n - k) + s;  // reverse the suffix of length k
        for (const string &c : {p, s})
            if (!have || c < best) {
                best = c;
                have = true;
            }
    }
    cout << best << '\n';
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String w = next();
        int n = w.length();
        String best = null;
        for (int k = 1; k <= n; k++) {
            String p = new StringBuilder(w.substring(0, k)).reverse() + w.substring(k);
            String s = w.substring(0, n - k) + new StringBuilder(w.substring(n - k)).reverse();
            if (best == null || p.compareTo(best) < 0) best = p;
            if (s.compareTo(best) < 0) best = s;
        }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	w := strings.TrimSpace(string(raw))
	n := len(w)
	best := ""
	for k := 1; k <= n; k++ {
		pre := []byte(w[:k])
		slices.Reverse(pre)
		suf := []byte(w[n-k:])
		slices.Reverse(suf)
		p := string(pre) + w[k:]   // reverse the prefix of length k
		s := w[:n-k] + string(suf) // reverse the suffix of length k
		if k == 1 || p < best {
			best = p
		}
		if s < best {
			best = s
		}
	}
	fmt.Println(best)
}
